-- ==============================================================================================
-- BASELINE — the tables this repository's migration history never created.
--
-- Generated by scripts/gen_baseline_migration.mjs from production's catalog. Do not hand-edit:
-- re-run the generator instead, so the file cannot drift from the database it describes.
--
-- 34 table(s) are ALTERed, INSERTed into and INDEXed by later migrations and created by
-- none of them. They exist on production and staging because they were made directly in the
-- database, so the written history could describe this platform but never rebuild it. That is
-- why the Supabase Preview check — which replays onto an EMPTY database — had never passed.
--
-- Every statement is idempotent. On production and staging this file is a no-op in full; on an
-- empty database it is the foundation everything after it assumes.
--
-- Foreign keys come after every table, never inline, because an inline reference to a table
-- created later is the exact defect this baseline exists to end.
-- ==============================================================================================

-- Extensions the column types depend on.
create extension if not exists vector;

-- Sequences backing serial-style defaults. Identity columns are not here: they make their own.
create sequence if not exists public.agent_knowledge_id_seq;
create sequence if not exists public.company_event_id_seq;
create sequence if not exists public.department_objective_id_seq;
create sequence if not exists public.documents_id_seq;
create sequence if not exists public.employee_kpi_id_seq;
create sequence if not exists public.inquiries_rfq_no_seq;
create sequence if not exists public.institutional_memory_id_seq;
create sequence if not exists public.spec_backlog_id_seq;

-- ── public.agent_knowledge ───────────────────────────────────────────────────────────────
create table if not exists public.agent_knowledge (
  id bigint default nextval('agent_knowledge_id_seq'::regclass),
  agent_key text,
  topic text,
  content text,
  priority integer default 5,
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  layer text default 'profession'::text,
  source_ref text,
  owner_agent text,
  version integer default 1,
  confidence numeric,
  validation_status text default 'unvalidated'::text,
  review_due date,
  supersedes_id bigint,
  constraint agent_knowledge_layer_check CHECK ((layer = ANY (ARRAY['company'::text, 'profession'::text, 'state'::text, 'experience'::text]))),
  constraint agent_knowledge_pkey PRIMARY KEY (id)
);
alter table public.agent_knowledge enable row level security;
create unique index if not exists agent_knowledge_cat_topic_uidx ON public.agent_knowledge USING btree (agent_key, topic) WHERE (agent_key ~~ 'cat:%'::text);
create index if not exists agent_knowledge_review_due_idx ON public.agent_knowledge USING btree (review_due) WHERE (validation_status <> 'quarantined'::text);
create index if not exists idx_agent_knowledge_key ON public.agent_knowledge USING btree (agent_key);

