  at timestamp with time zone default now(),
  actor text,
  action text,
  entity text,
  entity_id text,
  detail jsonb,
  ok boolean,
  err text,
  constraint os_audit_log_pkey PRIMARY KEY (id)
);
alter table public.os_audit_log enable row level security;
create index if not exists idx_os_audit_action ON public.os_audit_log USING btree (action);
create index if not exists idx_os_audit_actor ON public.os_audit_log USING btree (actor);
create index if not exists idx_os_audit_at ON public.os_audit_log USING btree (at DESC);
create index if not exists os_audit_log_action_idx ON public.os_audit_log USING btree (action, at DESC);
create index if not exists os_audit_log_actor_idx ON public.os_audit_log USING btree (actor, at DESC);
create index if not exists os_audit_log_at_idx ON public.os_audit_log USING btree (at DESC);

-- ── public.pricing_config ────────────────────────────────────────────────────────────────
create table if not exists public.pricing_config (
  id integer default 1,
  promo_reveal_rate numeric default 0.02,
  promo_reveal_cap numeric default 250,
  standard_reveal_rate numeric default 0.02,
  standard_reveal_cap numeric default 250,
  promo_until timestamp with time zone,
  supplier_free_count integer default 1000,
  supplier_reg_fee numeric default 1000,
  supplier_reg_period text default 'yearly'::text,
  refund_window_working_days integer default 3,
  updated_at timestamp with time zone default now(),
  auto_approve_suppliers boolean default false,
  supplier_reg_currency text default 'AED'::text,
  reveal_currency text default 'AED'::text,
  supplier_charging_starts date default '2027-08-01'::date,
  constraint pricing_config_currency_ck CHECK (((supplier_reg_currency = 'AED'::text) AND (reveal_currency = 'AED'::text))),
  constraint pricing_config_fee_range_ck CHECK (((supplier_reg_fee IS NULL) OR ((supplier_reg_fee >= (500)::numeric) AND (supplier_reg_fee <= (5000)::numeric)))),
  constraint pricing_config_period_ck CHECK ((supplier_reg_period = ANY (ARRAY['yearly'::text, 'monthly'::text]))),
  constraint pricing_config_singleton CHECK ((id = 1)),
  constraint pricing_config_pkey PRIMARY KEY (id)
);
alter table public.pricing_config enable row level security;

-- ── public.reviews ───────────────────────────────────────────────────────────────────────
create table if not exists public.reviews (
  id bigint generated always as identity,
  supplier_id bigint,
  customer_id uuid,
  inquiry_id uuid,
  transaction_id uuid,
  rating integer,
  comment text,
  created_at timestamp with time zone default now(),
  r_communication smallint,
  r_quality smallint,
  r_punctuality smallint,
  r_documentation smallint,
  r_after_sales smallint,
  r_compliance smallint,
  constraint reviews_r_after_sales_check CHECK (((r_after_sales >= 1) AND (r_after_sales <= 5))),
  constraint reviews_r_communication_check CHECK (((r_communication >= 1) AND (r_communication <= 5))),
  constraint reviews_r_compliance_check CHECK (((r_compliance >= 1) AND (r_compliance <= 5))),
  constraint reviews_r_documentation_check CHECK (((r_documentation >= 1) AND (r_documentation <= 5))),
  constraint reviews_r_punctuality_check CHECK (((r_punctuality >= 1) AND (r_punctuality <= 5))),
  constraint reviews_r_quality_check CHECK (((r_quality >= 1) AND (r_quality <= 5))),
  constraint reviews_rating_check CHECK (((rating >= 1) AND (rating <= 5))),
  constraint reviews_rating_range CHECK (((rating >= 1) AND (rating <= 5))) NOT VALID,
  constraint reviews_reason_required CHECK (((comment IS NOT NULL) AND (length(btrim(comment)) >= 10))) NOT VALID,
  constraint reviews_pkey PRIMARY KEY (id),
  constraint reviews_transaction_id_key UNIQUE (transaction_id)
);
alter table public.reviews enable row level security;
create index if not exists idx_reviews_customer_id ON public.reviews USING btree (customer_id);
create index if not exists idx_reviews_inquiry_id ON public.reviews USING btree (inquiry_id);
create index if not exists idx_reviews_supplier_id ON public.reviews USING btree (supplier_id);
create unique index if not exists reviews_one_per_job ON public.reviews USING btree (supplier_id, inquiry_id, customer_id);

-- ── public.skills_matrix ─────────────────────────────────────────────────────────────────
create table if not exists public.skills_matrix (
  agent_key text,
  skill text,
  rating integer,
  evidence text,
  updated_at timestamp with time zone default now(),
  constraint skills_matrix_rating_check CHECK (((rating >= 1) AND (rating <= 5))),
  constraint skills_matrix_pkey PRIMARY KEY (agent_key, skill)
);
alter table public.skills_matrix enable row level security;

-- ── public.spec_backlog ──────────────────────────────────────────────────────────────────
create table if not exists public.spec_backlog (
  id bigint default nextval('spec_backlog_id_seq'::regclass),
  source_doc text,
  area text,
  item text,
  spec_ref text,
  status text default 'pending'::text,
  verdict_at_audit text,
  evidence text,
  priority integer default 3,
  notes text,
  updated_at timestamp with time zone default now(),
  constraint spec_backlog_pkey PRIMARY KEY (id)
);
alter table public.spec_backlog enable row level security;
create unique index if not exists spec_backlog_spec_ref_uidx ON public.spec_backlog USING btree (spec_ref) WHERE (spec_ref IS NOT NULL);
create index if not exists spec_backlog_status_idx ON public.spec_backlog USING btree (status, priority);

-- ── public.undo_log ──────────────────────────────────────────────────────────────────────
create table if not exists public.undo_log (
  id uuid default gen_random_uuid(),
  table_name text,
  row_id text,
  op text,
  before jsonb,
  actor text,
  reverted boolean default false,
  created_at timestamp with time zone default now(),
  constraint undo_log_pkey PRIMARY KEY (id)
);
alter table public.undo_log enable row level security;
create index if not exists undo_log_created_idx ON public.undo_log USING btree (created_at DESC);

-- ── public.workflow ──────────────────────────────────────────────────────────────────────
create table if not exists public.workflow (
  workflow_key text,
  name text,
  trigger_event text,
  description text,
  active boolean default true,
  os_key text,
  constraint workflow_pkey PRIMARY KEY (workflow_key)
);
alter table public.workflow enable row level security;

-- ── public.workflow_step ─────────────────────────────────────────────────────────────────
create table if not exists public.workflow_step (
  workflow_key text,
  step_no integer,
  step text,
  actor_role text,
  action_class text,
  gate text,
  constraint workflow_step_pkey PRIMARY KEY (workflow_key, step_no)
);
alter table public.workflow_step enable row level security;
